import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"Ceph Performance Meeting 2022-07-14","description":"","frontmatter":{"title":"Ceph Performance Meeting 2022-07-14","date":"2022-07-14T00:00:00.000Z","updated":"2022-07-19T00:00:00.000Z","tags":["Ceph","性能优化","内存管理","分布式存储","蓝图存储"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Ceph_Performance_Meeting_2022-07-14.md","filePath":"posts/2022/Ceph_Performance_Meeting_2022-07-14.md","lastUpdated":1780460162000}'),l={name:"posts/2022/Ceph_Performance_Meeting_2022-07-14.md"};function i(n,e,s,p,g,u){return a(),o("div",null,[...e[0]||(e[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>Blue Store Zero Block Detection PR 性能问题</strong></p><ul><li><strong>讨论内容</strong>：会议讨论了Blue Store Zero Block Detection PR在Quincy版本中的性能问题，指出其在17.2.1版本中被默认关闭导致性能下降。</li><li><strong>决定事项</strong>：需要进一步分析性能下降的原因。</li><li><strong>后续行动</strong>：Laura将与DFG存储团队合作，深入研究17.2.0和17.2.1版本之间的性能差异。</li></ul></li><li><p><strong>内存使用问题与PG Log中的Dupe Ops跟踪</strong></p><ul><li><strong>讨论内容</strong>：讨论了PG Log中跟踪Dupe Ops时遇到的内存使用问题，指出损坏的Dupe条目会导致停止修剪，从而允许Dupe条目积累。</li><li><strong>决定事项</strong>：提出在OSD重启时，逐步修剪条目（每次10,000条）的解决方案。</li><li><strong>后续行动</strong>：将继续测试和验证该解决方案的有效性。</li></ul></li><li><p><strong>Snap Map性能影响</strong></p><ul><li><strong>讨论内容</strong>：讨论了Snap Map对性能的影响，特别是在Snapdragon和Clone Object Creation方面的性能问题。</li><li><strong>决定事项</strong>：需要设计针对性的测试来验证Snap Map的性能影响。</li><li><strong>后续行动</strong>：Gabri将与团队合作，设计并执行相关测试。</li></ul></li><li><p><strong>Smithy节点替换计划</strong></p><ul><li><strong>讨论内容</strong>：讨论了可能的资金支持用于替换Smithy节点，并提出了一个基于高能效的硬件配置方案。</li><li><strong>决定事项</strong>：需要尽快确定硬件配置，并在短时间内提交报价。</li><li><strong>后续行动</strong>：David Galloway将与团队合作，尽快确定硬件配置，并提交报价。</li></ul></li></ol><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>Laura和DFG存储团队将继续研究Blue Store Zero Block Detection PR的性能问题，并寻找解决方案。</li><li>团队将继续测试和验证PG Log中Dupe Ops跟踪的内存使用问题解决方案。</li><li>Gabri将与团队合作，设计并执行针对Snap Map性能影响的测试。</li><li>David Galloway将与团队合作，尽快确定Smithy节点替换的硬件配置，并提交报价。</li></ul><h4 id="其他事项" tabindex="-1">其他事项 <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项&quot;">​</a></h4><ul><li>会议中还讨论了其他潜在的性能优化和硬件升级问题，但未形成具体决定或行动计划。</li></ul><h4 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h4><p>会议涵盖了多个关键议题，包括性能优化、内存管理、硬件升级等，并制定了相应的后续行动计划。团队将继续合作，确保各项议题得到有效解决。</p>',9)])])}const d=t(l,[["render",i]]);export{h as __pageData,d as default};
